type Domain =
  | "AVOIP"
  | "HDBASET"
  | "PRESENTATION"
  | "MATRIX"
  | "VIDEO_WALL"
  | "MULTIVIEW"
  | "USB_EXTENSION"
  | "CONTROL"
  | "UNKNOWN";

type Role =
  | "Transceiver"
  | "Encoder"
  | "Decoder"
  | "Presentation Switcher"
  | "Matrix"
  | "Video Wall Processor"
  | "Multiview Processor"
  | "Extender"
  | "USB Extender"
  | "Controller"
  | "Unknown";

type Verdict = "Match" | "Better" | "Partial" | "Verify" | "Mismatch";

type FeatureFlags = {
  usbC?: boolean;
  usbRouting?: boolean;
  wireless?: boolean;
  conferencing?: boolean;
  mst?: boolean;
  multiview?: boolean;
  videoWall?: boolean;
  dante?: boolean;
  aes67?: boolean;
  scaling?: boolean;
  audioDeEmbed?: boolean;
  vga?: boolean;
  microphone?: boolean;
  hdmiOutput?: boolean;
  hdbtOutput?: boolean;
  simultaneousOutputs?: boolean;
  hdr?: boolean;
  receiverKit?: boolean;
  arc?: boolean;
  ethernet?: boolean;
  irRs232?: boolean;
  poc?: boolean;
  fibre?: boolean;
  zeroLatency?: boolean;
  lossless?: boolean;
  lowBandwidth?: boolean;
  tenGig?: boolean;
  oneGig?: boolean;
  hdbt3?: boolean;
  hdbt2?: boolean;
  control?: boolean;
};

type ProductProfile = {
  manufacturer: string;
  sku: string;
  title: string;
  summary: string;
  domain: Domain;
  role: Role;
  transport: string;
  family: string;
  maxResolution: string;
  resolutionRank: number;
  chroma: string;
  latency: string;
  performanceTier: string;
  features: FeatureFlags;
  sourceUrl?: string;
  inputCount?: number;
  outputCount?: number;
  evidence?: string[];
};

type WyreStormCandidate = ProductProfile & {
  commercialPosition: string;
  whyConsider: string;
};

type ScoredCandidate = WyreStormCandidate & {
  score: number;
  confidence: number;
  scoreNotes: string[];
};

type CompareRow = {
  label: string;
  competitor: string;
  wyrestorm: string;
  verdict: Verdict;
  note: string;
};

type Swot = {
  strengths: string[];
  weaknesses: string[];
  opportunities: string[];
  threats: string[];
};

type CompareRecord = {
  id: string;
  savedAt: string;
  manufacturer: string;
  model: string;
  productUrl: string;
  context: string;
  competitor: ProductProfile;
  shortlist: ScoredCandidate[];
  matchScore?: number;
  rows: CompareRow[];
  swot: Swot;
  reviewNotes: string[];
  lookupMode: string;
};

type TextInputField = "sku" | "productUrl" | "context";

type TextInputHistoryStore = {
  version: number;
  updatedAt: string;
  entries: Record<string, string[]>;
};

type TextInputSuggestions = {
  sku: string[];
  productUrl: string[];
  context: string[];
};

type BackendPayload = {
  ok?: boolean;
  error?: string;
  record?: Record<string, unknown>;
  competitor?: Record<string, unknown>;
  competitorProfile?: Record<string, unknown>;
  summary?: string;
  title?: string;
  keySpecs?: string[];
  resolvedUrl?: string;
  sourceUrl?: string;
};

